 const day=dayNameForDate(date),training=trainingDayNames(profile);
 return arr.filter(a=>{if(a.preferred_days?.length)return a.preferred_days.some(x=>slugText(x).startsWith(slugText(day).slice(0,3)));const n=Math.max(1,Math.min(7,+a.frequency_per_week||2)),kind=slugText(a.name),rest=DAYS.filter(d=>!training.includes(d)),order=/yoga|pilates/.test(kind)?[...rest,...training]:/sauna/.test(kind)?[...training,...rest]:/corrid|esteira|caminh|bicic|elipt/.test(kind)?[...training,...rest]:DAYS;return [...new Set(order)].slice(0,n).includes(day)}).map((a,i)=>({key:`routine_${a.key}_${date}`,name:a.name,duration_min:a.duration_min||null,notes:training.includes(day)?'Integrado à rotina de treino do dia':'Sessão programada da rotina',source:'routine'}))
