function addC(t,w='coach'){if(S.batchApplying&&w==='coach')return;const d=document.createElement('div');d.className='bubble '+w;d.innerHTML=t;$('#coachTalk').appendChild(d);$('#coachTalk').scrollTop=$('#coachTalk').scrollHeight}
function addFoodToEditedMeal(enc){const name=decodeURIComponent(enc),f=S.foods.find(x=>x.name===name),m=S.plan.meals.find(x=>x.key===S.editingMealKey);if(!f||!m)return;const existing=m.foodItems.find(x=>x.name===f.name);if(existing)existing.grams+=(existing.baseAmount||portionInfo(existing.portion).amount);else m.foodItems.push(foodItemFromLib(f));renderEditMealItems();$('#editFoodSearch').value='';$('#editFoodResults').innerHTML=''}
async function applyCalories(next){if(!next||next<1000||next>6000)throw new Error('Meta calórica fora de uma faixa válida.');const carb=Math.max(80,Math.round((next-S.plan.prot*4-S.plan.fat*9)/4));return applyNutritionPlan({calories:next,protein_g:S.plan.prot,carbs_g:carb,fat_g:S.plan.fat})}
