async function deleteCurrentMeal(){const m=S.plan.meals.find(x=>x.key===S.editingMealKey);if(!m||!confirm('Excluir esta refeição deste dia?'))return;await sb.from('meal_logs').upsert({user_id:session.user.id,log_date:S.currentDate,meal_key:m.key,meal_name:m.name,meal_time:m.time,foods:[],kcal:0,protein_g:0,carbs_g:0,fat_g:0,completed:false,deleted:true},{onConflict:'user_id,log_date,meal_key'}).catch(()=>{});S.plan.meals=S.plan.meals.filter(x=>x.key!==m.key);closeEditMeal();renderMeals();progress();toast('Refeição excluída deste dia')}
