async function saveActivitiesManager(){const arr=normalizeActivities(S.activityDraft.filter(a=>String(a.name||'').trim()));const text=arr.map(activityLabel).join('; ');await updateProfileFields({other_activities:arr,other_activities_text:text||null});S.p.other_activities=arr;S.p.other_activities_text=text||null;closeActivitiesManager();renderActivities();renderProfile();toast('Atividades da rotina atualizadas ✓')}
function isActivityLib(x){return x?.group==='Atividade'}
function exerciseFilterGroup(x){if(isActivityLib(x))return'activities';const g=slugText(x.group);if(g.includes('peitoral'))return'chest';if(g.includes('costas'))return'back';if(g.includes('biceps')||g.includes('antebraco'))return'biceps';if(g.includes('triceps'))return'triceps';if(g.includes('ombro'))return'shoulders';if(g.includes('perna'))return'legs';return'all'}
function setExerciseFilter(f){S.exerciseFilter=f;$$('#exerciseFilters button').forEach(b=>b.classList.toggle('active',b.dataset.ef===f));renderExerciseLibrary()}
function openEditExercise(key=null){S.editingExerciseKey=key;const e=key?S.plan.exercises.find(x=>x.key===key):null;S.exerciseFilter='all';$('#editExerciseTitle').textContent=e?'Editar exercício':'Adicionar exercício / atividade';$('#exName').value=e?.name||'';$('#exSets').value=e?.sets||Number((e?.scheme?.match(/\d+/)||[3])[0]);$('#exReps').value=e?.reps||(e?.scheme?.split('×')[1]||'8–12').trim();$('#exRest').value=e?.rest||90;$('#exTarget').value=e?.targetLoad||'';$('#activityFields').style.display='none';$('#strengthFields').style.display='grid';$$('#exerciseFilters button').forEach(b=>b.classList.toggle('active',b.dataset.ef==='all'));renderExerciseLibrary();$('#editExerciseModal').classList.add('open')}
function closeEditExercise(){S.editingExerciseKey=null;$('#editExerciseModal').classList.remove('open')}
function renderExerciseLibrary(){const q=slugText($('#exerciseSearch')?.value||''),f=S.exerciseFilter||'all';$('#exerciseResults').innerHTML=EXERCISE_LIBRARY.filter(x=>(f==='all'||exerciseFilterGroup(x)===f)&&(!q||slugText(`${x.name} ${x.group} ${x.muscles}`).includes(q))).slice(0,100).map(x=>`<button onclick="chooseExercise('${x.id}')"><b>${x.name}</b><small>${x.group} • ${x.muscles}</small></button>`).join('')||'<p class="emptyLibrary">Nenhum item encontrado.</p>'}
function chooseExercise(id){const x=EXERCISE_LIBRARY.find(y=>y.id===id);if(!x)return;$('#exName').value=x.name;const act=isActivityLib(x);$('#strengthFields').style.display=act?'none':'grid';$('#activityFields').style.display=act?'grid':'none';$('#activityTypeHint').textContent=act?activityInputHint(x.name):''}
function activityInputHint(name){const n=slugText(name);if(/sauna/.test(n))return'Sauna: informe sessões e minutos por sessão.';if(/caminh|esteira|corrid|bicic|elipt|natac/.test(n))return'Você pode registrar tempo e/ou distância.';return'Informe a duração da aula, sessão ou atividade.'}
async function saveExerciseEdit(){const name=$('#exName').value.trim();if(!name)return toast('Escolha ou informe um exercício/atividade.');const lib=EXERCISE_LIBRARY.find(x=>slugText(x.name)===slugText(name))||{};if(isActivityLib(lib)||S.exerciseFilter==='activities'){const duration=+$('#actDuration').value||null,distance=+$('#actDistance').value||null,sessions=+$('#actSessions').value||null,item={key:'manual_'+Date.now(),name,duration_min:duration,distance_km:distance,sessions,notes:$('#actNotes').value.trim(),source:'manual_day'};S.plan.activities=S.plan.activities||[];S.plan.activities.push(item);await persistWorkoutPlan();closeEditExercise();renderEx();progress();return toast('Atividade incluída no treino de hoje ✓')}const sets=+$('#exSets').value||3,reps=$('#exReps').value.trim()||'8–12',rest=+$('#exRest').value||90,targetLoad=+$('#exTarget').value||null;const obj={key:S.editingExerciseKey||'custom_'+Date.now(),name,sets,reps,rest,targetLoad,scheme:`${sets} × ${reps}`,group:lib.group||'Personalizado',muscles:lib.muscles||lib.group||'Personalizado',equipment:lib.equipment||''};const ix=S.plan.exercises.findIndex(x=>x.key===S.editingExerciseKey);if(ix>=0)S.plan.exercises[ix]={...S.plan.exercises[ix],...obj};else S.plan.exercises.push(obj);await persistWorkoutPlan();closeEditExercise();renderEx();progress();toast('Treino atualizado ✓')}
async function deleteExerciseEdit(){if(!S.editingExerciseKey)return closeEditExercise();S.plan.exercises=S.plan.exercises.filter(x=>x.key!==S.editingExerciseKey);S.ex.delete(S.editingExerciseKey);await persistWorkoutPlan();closeEditExercise();renderEx();progress();toast('Exercício excluído ✓')}
async function moveExercise(key,dir){const i=S.plan.exercises.findIndex(x=>x.key===key),j=i+dir;if(i<0||j<0||j>=S.plan.exercises.length)return;[S.plan.exercises[i],S.plan.exercises[j]]=[S.plan.exercises[j],S.plan.exercises[i]];await persistWorkoutPlan();renderEx()}
async function persistWorkoutPlan(){const {error}=await sb.from('workout_plans').upsert({user_id:session.user.id,plan_date:S.currentDate,exercises:S.plan.exercises,activities:S.plan.activities||[]},{onConflict:'user_id,plan_date'});if(error)throw error}
async function togEx(key){S.ex.has(key)?S.ex.delete(key):S.ex.add(key);const e=S.plan.exercises.find(x=>x.key===key);await sb.from('exercise_logs').upsert({user_id:session.user.id,log_date:S.currentDate,exercise_key:key,exercise_name:e.name,completed:S.ex.has(key)},{onConflict:'user_id,log_date,exercise_key'});await persistDaily();renderEx();progress()}
function portionInfo(portion,fallbackUnit='g'){const s=String(portion||'').trim().toLowerCase().replace(/ℓ/g,'l'),m=s.match(/([\d.,]+)\s*(kg|g|ml|l)\b/),n=s.match(/([\d.,]+)/);if(m){let amount=Math.max(.1,Number(m[1].replace(',','.'))||100),unit=m[2];if(unit==='kg'){amount*=1000;unit='g'}else if(unit==='l'){amount*=1000;unit='ml'}return{amount,unit}}return n?{amount:Math.max(.1,Number(n[1].replace(',','.'))||100),unit:fallbackUnit}:{amount:100,unit:fallbackUnit}}
function foodItemFromLib(f,amount=null){const fallback=(f.cat==='drink')?'ml':'g',pi=portionInfo(f.portion,fallback),grams=amount==null?pi.amount:+amount;return{name:f.name,grams:Math.max(1,grams),baseAmount:pi.amount,unit:pi.unit,kcal:+f.kcal||0,p:+f.p||0,c:+f.c||0,f:+f.f||0,portion:f.portion||`${pi.amount} ${pi.unit}`}}
function normalizeFoodItems(items){return (items||[]).map(x=>{if(typeof x==='object'){const lib=S.foods.find(f=>f.name.toLowerCase()===String(x.name||'').toLowerCase()),pi=portionInfo(x.portion||lib?.portion),base=+x.baseAmount||pi.amount,grams=x.grams!=null?+x.grams:(+x.qty||1)*base;return{name:x.name||lib?.name||'Alimento',grams:Math.max(1,grams),baseAmount:base,unit:x.unit||pi.unit,kcal:+(x.kcal??lib?.kcal)||0,p:+(x.p??x.protein_g??lib?.p)||0,c:+(x.c??x.carbs_g??lib?.c)||0,f:+(x.f??x.fat_g??lib?.f)||0,portion:x.portion||lib?.portion||`${base} ${pi.unit}`}};const txt=String(x).replace(/^\d+×\s*/,''),lib=S.foods.find(f=>f.name.toLowerCase()===txt.toLowerCase());return lib?foodItemFromLib(lib):{name:txt,grams:100,baseAmount:100,unit:'g',kcal:0,p:0,c:0,f:0,portion:'100 g'}})}
function itemTotals(x){const base=Math.max(.1,+x.baseAmount||portionInfo(x.portion).amount),factor=(+x.grams||base)/base;return{kcal:(+x.kcal||0)*factor,p:(+x.p||0)*factor,c:(+x.c||0)*factor,f:(+x.f||0)*factor}}
function foodLabel(x){return `${x.name} (${Math.round(+x.grams||0)} ${x.unit||'g'})`}
function realisticFoodRange(item){const n=normName(item?.name||''),lib=findFoodSmart(item?.name||''),cat=lib?.cat||'';let min=20,max=200;
 if(cat==='protein'){min=60;max=220}
 if(cat==='carb'){min=40;max=220}
 if(cat==='fruit'){min=60;max=220}
 if(cat==='veg'){min=50;max=250}
 if(cat==='dairy'){min=50;max=200}
 if(cat==='fat'){min=5;max=50}
 if(cat==='supp'){min=5;max=80}
 if(cat==='drink'){min=100;max=500}
 if(/cottage|ricota|queijo|requeijao/.test(n)){min=30;max=150}
 if(/morango|mirtilo|framboesa|amora/.test(n)){min=80;max=200}
 if(/banana|maca|pera|mamao|manga|laranja|kiwi|uva/.test(n)){min=70;max=220}
 if(/aveia|granola|muesli/.test(n)){min=15;max=70}
 if(/castanha|amendoim|amendoa|nozes|pistache|pasta de amendoim|tahine/.test(n)){min=5;max=40}
 if(/azeite/.test(n)){min=3;max=20}
 if(/whey|caseina|albumina|proteina vegetal/.test(n)){min=15;max=60}
 if(/arroz|macarrao|batata|mandioca|inhame|cara|cuscuz|quinoa|polenta/.test(n)){min=50;max=200}
 if(/feijao|lentilha|grao-de-bico|ervilha/.test(n)){min=40;max=160}
 if(/frango|patinho|picanha|contrafile|alcatra|maminha|file mignon|peixe|tilapia|salmao|atum|sardinha|camarao|lombo|pernil/.test(n)){min=70;max=220}
 return{min,max}}
function clampFoodAmount(item,amount){const r=realisticFoodRange(item);return Math.max(r.min,Math.min(r.max,Math.round((+amount||r.min)/5)*5))}
function mealComplementCandidates(items){const cats=new Set((items||[]).map(x=>findFoodSmart(x.name)?.cat));const pref=[];if(!cats.has('protein'))pref.push('Iogurte proteico morango','Ovo inteiro','Peito de frango grelhado','Queijo cottage');if(!cats.has('carb'))pref.push('Aveia em flocos','Pão integral','Arroz branco cozido','Batata inglesa cozida');if(!cats.has('fruit'))pref.push('Banana nanica','Maçã gala','Morango');pref.push('Iogurte natural','Aveia em flocos','Banana nanica','Pão integral');return pref.map(findFoodSmart).filter(Boolean)}
function balanceMealRealistically(items,target){if(!items.length)return items;for(const x of items)x.grams=clampFoodAmount(x,x.grams);let kcal=items.reduce((a,x)=>a+itemTotals(x).kcal,0),tries=0;while(target-kcal>80&&items.length<5&&tries++<6){const f=mealComplementCandidates(items).find(f=>!items.some(x=>normName(x.name)===normName(f.name)));if(!f)break;const it=foodItemFromLib(f);it.grams=clampFoodAmount(it,it.baseAmount);items.push(it);kcal=items.reduce((a,x)=>a+itemTotals(x).kcal,0)}return items}
function hydrateDefaultMeals(){if(!S.foods.length||!S.plan?.meals)return;for(const m of S.plan.meals){if(m.foodItems?.length)continue;const items=(m.foods||[]).map(n=>findFoodSmart(n)).filter(Boolean).map(f=>foodItemFromLib(f));m.foodItems=items;if(!items.length)continue;let k=items.reduce((sum,x)=>sum+itemTotals(x).kcal,0);if(k>0){const scale=Math.max(.55,Math.min(2.1,(+m.target||k)/k));for(const x of items)x.grams=clampFoodAmount(x,x.grams*scale);balanceMealRealistically(items,+m.target||k)}enrichMeal(m)}}
function enrichMeal(m){if(!m.foodItems)m.foodItems=normalizeFoodItems(m.foods);const t=mealTotals(m);if(t.kcal>0){m.target=Math.round(t.kcal);m.protein=t.p;m.carbs=t.c;m.fat=t.f}m.foods=m.foodItems.map(foodLabel);return m}
function mealTotals(m){return (m.foodItems||[]).reduce((a,x)=>{const z=itemTotals(x);return{kcal:a.kcal+z.kcal,p:a.p+z.p,c:a.c+z.c,f:a.f+z.f}},{kcal:0,p:0,c:0,f:0})}
function dayNutrition(){return S.plan.meals.map(enrichMeal).reduce((a,m)=>{const z=mealTotals(m);a.kcal+=z.kcal;a.p+=z.p;a.c+=z.c;a.f+=z.f;return a},{kcal:0,p:0,c:0,f:0})}
function consumedNutrition(){return S.plan.meals.filter(m=>S.mealsDone.has(m.key)).reduce((a,m)=>{const z=mealTotals(m);a.kcal+=z.kcal;a.p+=z.p;a.c+=z.c;a.f+=z.f;return a},{kcal:0,p:0,c:0,f:0})}
function updateDayNutrition(){const used=consumedNutrition();$('#cal').textContent=`${Math.round(used.kcal).toLocaleString('pt-BR')} kcal`;$('#prot').textContent=`${Math.round(used.p)} g`;$('#carb').textContent=`${Math.round(used.c)} g`;$('#fat').textContent=`${Math.round(used.f)} g`;$('#calPlan').textContent=`Plano do dia: ${Math.round(S.plan.cal).toLocaleString('pt-BR')} kcal`;$('#protPlan').textContent=`Plano: ${Math.round(S.plan.prot)} g`;$('#carbPlan').textContent=`Plano: ${Math.round(S.plan.carb)} g`;$('#fatPlan').textContent=`Plano: ${Math.round(S.plan.fat)} g`}
function renderMeals(){S.plan.meals.sort((a,b)=>(a.time||'').localeCompare(b.time||''));$('#mealList').innerHTML=S.plan.meals.map(m=>{enrichMeal(m);const t=mealTotals(m);return `<article class="item ${S.mealsDone.has(m.key)?'done':''}"><div><span>${m.time} • ${Math.round(t.kcal||m.target)} kcal • P${Math.round(t.p||0)} C${Math.round(t.c||0)} G${Math.round(t.f||0)}</span><h3>${m.name}</h3><p>${m.foods.join(' + ')||'Sem alimentos'}</p></div><div class="mealButtons"><button class="soft mini" onclick="openEditMeal('${m.key}')">EDITAR</button><button class="check" onclick="togMeal('${m.key}')">${S.mealsDone.has(m.key)?'✓':'○'}</button></div></article>`}).join('');updateDayNutrition()}
async function togMeal(key){S.mealsDone.has(key)?S.mealsDone.delete(key):S.mealsDone.add(key);const m=S.plan.meals.find(x=>x.key===key);await persistMeal(m);await persistDaily();renderMeals();progress()}
const BEVERAGE_TYPES={
 water:{label:'Água',hydration:true,group:'hydration'},
 tea:{label:'Chá',hydration:true,group:'hydration'},
 natural_juice:{label:'Suco natural',hydration:true,group:'hydration'},
 zero_soda:{label:'Refrigerante zero',hydration:false,group:'beyond'},
 soda:{label:'Refrigerante comum',hydration:false,group:'beyond'},
 industrial_juice:{label:'Suco industrializado',hydration:false,group:'beyond'},
 beer:{label:'Cerveja',hydration:false,group:'beyond',alcohol:true},
 alcohol:{label:'Outra bebida alcoólica',hydration:false,group:'beyond',alcohol:true},
 other:{label:'Outra bebida',hydration:false,group:'beyond'}
};
async function ensureHydrationBaseline(){if(S.beverages.length||S.water<=0)return;const ml=Math.round(S.water*1000);const {data,error}=await sb.from('beverage_logs').insert({user_id:session.user.id,log_date:S.currentDate,beverage_type:'water',beverage_label:'Água (saldo anterior)',volume_ml:ml,hydration_counts:true,quality_group:'hydration',source:'migration'}).select().single();if(error)throw error;S.beverages.push(data)}
async function addBeverage(type,ml,label=null,source='manual'){ml=Math.round(Number(ml)||0);if(ml<=0)return;const meta=BEVERAGE_TYPES[type]||BEVERAGE_TYPES.other;await ensureHydrationBaseline();const row={user_id:session.user.id,log_date:S.currentDate,beverage_type:type,beverage_label:label||meta.label,volume_ml:ml,hydration_counts:!!meta.hydration,quality_group:meta.group,source};const {data,error}=await sb.from('beverage_logs').insert(row).select().single();if(error)throw error;S.beverages.push(data);S.beverageHistory.unshift(data);if(meta.hydration)S.water+=ml/1000;else S.beyondMl+=ml;await persistDaily();renderWater();progress();renderHist();renderMonthly();toast(`+${ml} ml de ${row.beverage_label} registrados ✓`)}
async function addWater(v){v=Number(v)||0;if(v<=0)return;await addBeverage('water',v*1000,'Água','shortcut')}
async function addCustomWater(){const el=$('#waterCustomMl'),ml=Number(String(el?.value||'').replace(',','.'));if(!ml||ml<=0)return toast('Digite uma quantidade válida em ml.');await addBeverage('water',ml,'Água','manual');el.value=''}
async function addSelectedBeverage(){const type=$('#beverageType')?.value||'tea',el=$('#beverageMl'),ml=Number(String(el?.value||'').replace(',','.'));if(!ml||ml<=0)return toast('Digite uma quantidade válida em ml.');await addBeverage(type,ml);el.value=''}
async function deleteBeverage(id){const item=S.beverages.find(x=>x.id===id);if(!item)return;const {error}=await sb.from('beverage_logs').delete().eq('id',id).eq('user_id',session.user.id);if(error)return toast(error.message);S.beverages=S.beverages.filter(x=>x.id!==id);S.beverageHistory=S.beverageHistory.filter(x=>x.id!==id);if(item.hydration_counts)S.water=Math.max(0,S.water-(+item.volume_ml||0)/1000);else S.beyondMl=Math.max(0,S.beyondMl-(+item.volume_ml||0));await persistDaily();renderWater();progress();renderHist();renderMonthly();toast('Registro removido ✓')}
function beverageQuality(){const beyond=S.beverages.filter(x=>!x.hydration_counts).reduce((a,x)=>a+(+x.volume_ml||0),0),alc=S.beverages.filter(x=>['beer','alcohol'].includes(x.beverage_type)).reduce((a,x)=>a+(+x.volume_ml||0),0),hydr=Math.max(0,S.water*1000),ratio=beyond/Math.max(1,beyond+hydr);let penalty=Math.min(12,ratio*18)+Math.min(8,alc/500*2);return{beyond,alc,quality:Math.max(0,Math.round(100-penalty)),penalty:Math.round(penalty)}}
function renderWater(){const q=beverageQuality();$('#waterNow').textContent=S.water.toFixed(2).replace('.',',')+' L';$('#hWater').textContent=S.water.toFixed(2).replace('.',',')+' / '+S.plan.water.toFixed(1).replace('.',',')+' L';if($('#beyondNow'))$('#beyondNow').textContent=(q.beyond/1000).toFixed(2).replace('.',',')+' L';if($('#beverageQuality'))$('#beverageQuality').textContent=q.beyond?`Qualidade das bebidas: ${q.quality}%`:'Nenhuma bebida “além da hidratação” registrada hoje.';if($('#beverageList'))$('#beverageList').innerHTML=S.beverages.length?S.beverages.slice().reverse().map(x=>`<div class="beverageRow"><div><b>${x.beverage_label}</b><small>${x.hydration_counts?'Conta na hidratação':'Além da hidratação'} • ${Math.round(+x.volume_ml||0)} ml</small></div><button class="dangerSoft mini" onclick="deleteBeverage('${x.id}')">REMOVER</button></div>`).join(''):'<p class="emptyBeverage">Nenhuma bebida detalhada registrada neste dia.</p>'}
function scoreFor(t,f,w,a=null,sl=null,bevQuality=100){let parts=[['t',t,.30],['f',f,.30],['w',w,.15]],known=.75;if(a!==null){parts.push(['a',a,.10]);known+=.10}if(sl!==null){parts.push(['s',sl,.15]);known+=.15}const adherence=parts.reduce((z,x)=>z+x[1]*x[2],0)/known,beverageImpact=Math.max(0,(100-bevQuality)*.20);return Math.max(0,Math.min(100,Math.round(adherence-beverageImpact)))}
function metrics(){const totalTraining=(S.plan.exercises?.length||0)+(S.plan.activities?.length||0),doneTraining=S.ex.size+S.activitiesDone.size,t=totalTraining?doneTraining/totalTraining*100:0,f=S.plan.meals.length?S.mealsDone.size/S.plan.meals.length*100:0,w=Math.min(100,S.water/S.plan.water*100),hasSteps=!!(+S.p.steps_goal&&S.steps>0),a=hasSteps?Math.min(100,S.steps/+S.p.steps_goal*100):null,sleepTarget=S.plan.sleepTarget||smartSleepTarget(),sl=S.sleepHours==null?null:Math.min(100,S.sleepHours/sleepTarget*100),bq=beverageQuality(),vals=[t,f,w,...(a===null?[]:[a]),...(sl===null?[]:[sl])],pct=Math.round(vals.reduce((x,y)=>x+y,0)/vals.length),score=scoreFor(t,f,w,a,sl,bq.quality);return{t,f,w,a,sl,pct,score,beverageQuality:bq.quality,beyondMl:bq.beyond}}
function setMiniRing(id,pct){const p=Math.max(0,Math.min(100,Math.round(+pct||0))),el=$('#'+id+'MiniRing'),tx=$('#'+id+'MiniPct');if(el)el.style.setProperty('--mini-pct',p);if(tx)tx.textContent=p}
function progress(){const {t,f,w,a,sl,pct,score}=metrics(),known=[t,f,w,a,sl].filter(x=>x!==null),areas=known.filter(x=>x>=95).length;$('#pct').textContent=pct;$('#ring').style.background=`conic-gradient(var(--green) 0 ${pct}%,#e4e9e5 ${pct}%)`;$('#daySub').textContent=areas+' de '+known.length+' áreas na meta';const totalT=(S.plan.exercises?.length||0)+(S.plan.activities?.length||0),doneT=S.ex.size+S.activitiesDone.size;$('#hTrain').textContent=doneT+'/'+totalT+' itens de treino';$('#hFood').textContent=S.mealsDone.size+'/'+S.plan.meals.length+' refeições';setMiniRing('train',t);setMiniRing('food',f);setMiniRing('water',w);updateStepsMiniRing();setMiniRing('sleep',sl||0);const ht=$('#hSleep');if(ht)ht.textContent=(S.sleepHours==null?'—':S.sleepHours.toFixed(1).replace('.',',')+' h')+' / '+(S.plan.sleepTarget||smartSleepTarget()).toFixed(1).replace('.',',')+' h';$('#score').textContent=score;$('#scoreText').textContent=pct>75?'EVOLUÇÃO FAVORÁVEL':pct>35?'EM ANDAMENTO':'BASELINE';$('#dayStatus').textContent=S.dayStatus==='completed'?'DIA CONCLUÍDO':'DIA EM ANDAMENTO';$('#saveDay').textContent=S.dayStatus==='completed'?'CONCLUIR NOVAMENTE / ATUALIZAR DIA ✓':'CONCLUIR MEU DIA ✓'}
async function persistDaily(status=S.dayStatus==='completed'?'completed':'in_progress'){const {t,f,w,a,score,beverageQuality,beyondMl}=metrics();const {error}=await sb.from('daily_logs').upsert({user_id:session.user.id,log_date:S.currentDate,training_pct:t,nutrition_pct:f,hydration_pct:w,activity_pct:a,water_l:S.water,beyond_hydration_ml:beyondMl,beverage_quality_pct:beverageQuality,score,status},{onConflict:'user_id,log_date'});if(error)throw error}
function openSleepToday(){$('#sleepTodayHours').value=S.sleepHours==null?'':S.sleepHours;$('#sleepTodayGoal').textContent='Meta inteligente do Σ Coach: '+(S.plan.sleepTarget||smartSleepTarget()).toFixed(1).replace('.',',')+' h';$('#sleepTodayModal').classList.add('open')}
function closeSleepToday(){$('#sleepTodayModal').classList.remove('open')}
async function saveSleepToday(){const hours=Number(String($('#sleepTodayHours').value).replace(',','.'));if(!hours||hours<1||hours>16)return toast('Informe quantas horas você dormiu.');const {error}=await sb.from('sleep_logs').upsert({user_id:session.user.id,log_date:S.currentDate,hours,target_hours:S.plan.sleepTarget||smartSleepTarget(),source:'user'},{onConflict:'user_id,log_date'});if(error)return toast(error.message);S.sleepHours=hours;S.sleepHistory=[{user_id:session.user.id,log_date:S.currentDate,hours,target_hours:S.plan.sleepTarget||smartSleepTarget(),source:'user'},...S.sleepHistory.filter(x=>x.log_date!==S.currentDate)];closeSleepToday();progress();await persistDaily();renderHist();renderMonthly();toast('Sono registrado ✓')}
function requestFinishDay(){const m=metrics();$('#finishDayText').innerHTML=`Seu dia está em <b>${m.pct}%</b>. Você pode concluir mesmo com itens pendentes — é justamente assim que o Σ Radar aprende com a rotina real.`;$('#finishDaySummary').innerHTML=`<div><span>TREINO</span><b>${S.ex.size}/${S.plan.exercises.length}</b></div><div><span>REFEIÇÕES</span><b>${S.mealsDone.size}/${S.plan.meals.length}</b></div><div><span>HIDRATAÇÃO</span><b>${S.water.toFixed(1).replace('.',',')} / ${S.plan.water.toFixed(1).replace('.',',')} L</b></div><div><span>ALÉM DA HIDRATAÇÃO</span><b>${(S.beyondMl/1000).toFixed(1).replace('.',',')} L</b></div><div><span>Σ SCORE</span><b>${m.score}</b></div>`;$('#finishDayModal').classList.add('open')}
