async function confirmFinishDay(){try{await persistDaily('completed');S.dayStatus='completed';closeFinishDay();const isSunday=dayNameForDate(S.currentDate)==='Domingo';if(isSunday){const {data:h}=await sb.from('daily_logs').select('*').eq('user_id',session.user.id).order('log_date',{ascending:false}).limit(120);S.history=h||S.history;renderApp();toast('Domingo registrado. Se os 7 dias estiverem concluídos, o fechamento semanal está liberado.');return}toast('Dia salvo. Abrindo o próximo registro…');setTimeout(async()=>await selectDay(dateAdd(S.currentDate,1)),550)}catch(e){toast('Não consegui salvar: '+(e.message||e))}}
function summarizeBeverages(rows){const out={hydration:0,beyond:0,types:{}};for(const x of rows||[]){const ml=+x.volume_ml||0;if(x.hydration_counts)out.hydration+=ml;else out.beyond+=ml;const k=x.beverage_label||BEVERAGE_TYPES[x.beverage_type]?.label||x.beverage_type||'Outra';out.types[k]=(out.types[k]||0)+ml}return out}
function beverageBreakdownText(rows){const z=summarizeBeverages(rows),parts=Object.entries(z.types).filter(([_,ml])=>ml>0).sort((a,b)=>b[1]-a[1]).map(([n,ml])=>`${n}: ${(ml/1000).toFixed(1).replace('.',',')} L`);return parts.length?parts.join(' • '):'Nenhuma bebida detalhada registrada.'}

function weekRange(date=S.currentDate||localDate()){const start=mondayOf(date);return{start,end:dateAdd(start,6),dates:Array.from({length:7},(_,i)=>dateAdd(start,i))}}
function completedWeekDays(range=weekRange()){return S.history.filter(x=>range.dates.includes(x.log_date)&&x.status==='completed')}
function absenceRows(start,end){return S.activityHistory.filter(x=>x.activity_key==='gym_absence'&&x.log_date>=start&&x.log_date<=end)}
function previousWeeklyReview(start){return (S.weeklyReviews||[]).filter(x=>x.week_start<start).sort((a,b)=>String(b.week_start).localeCompare(String(a.week_start)))[0]||null}
function compactPreviousWeeklyReview(x){if(!x)return null;return{week_start:x.week_start,average_score:+x.average_score||null,training_pct:+x.training_pct||null,nutrition_pct:+x.nutrition_pct||null,hydration_pct:+x.hydration_pct||null,summary:x.summary||'',keep:x.keep_text||'',increase:x.increase_text||'',reduce:x.reduce_text||'',next:x.proposed_changes?.next||'',context:x.proposed_changes?.context||null}}
function reviewContext(start,end,mode){const prev=mode==='weekly'?compactPreviousWeeklyReview(previousWeeklyReview(start)):null,sleep=S.sleepHistory.filter(x=>x.log_date>=start&&x.log_date<=end),sleepAvg=sleep.length?sleep.reduce((a,x)=>a+(+x.hours||0),0)/sleep.length:null,sleepTargetAvg=sleep.length?sleep.reduce((a,x)=>a+(+x.target_hours||smartSleepTarget()),0)/sleep.length:smartSleepTarget();return{mode,start,end,previous_weekly_review:prev,profile:{goal:S.p.goal_text,training_days:S.p.training_days,minutes_per_session:S.p.minutes_per_session,experience:S.p.experience,activities:S.p.other_activities,weight:S.p.current_weight_kg,target_weight:S.p.target_weight_kg,sleep_hours:S.p.sleep_hours,smart_sleep_target:smartSleepTarget(),steps_goal:S.p.steps_goal},daily_logs:S.history.filter(x=>x.log_date>=start&&x.log_date<=end),activity_logs:S.activityHistory.filter(x=>x.log_date>=start&&x.log_date<=end),beverages:S.beverageHistory.filter(x=>x.log_date>=start&&x.log_date<=end),body_logs:S.bodyHistory.filter(x=>x.log_date>=start&&x.log_date<=end),load_logs:S.loadHistory.filter(x=>x.log_date>=start&&x.log_date<=end),sleep_logs:sleep,sleep_summary:{known_days:sleep.length,average_hours:sleepAvg,target_average_hours:sleepTargetAvg,adherence_pct:sleepAvg===null?null:Math.round(Math.min(100,sleepAvg/sleepTargetAvg*100))},absence_reasons:absenceRows(start,end).map(x=>({date:x.log_date,reason:x.notes||'não informado'}))}}
function fallbackReview(ctx){const d=ctx.daily_logs.filter(x=>x.status==='completed'),avg=k=>d.length?Math.round(d.reduce((a,x)=>a+(+x[k]||0),0)/d.length):0,abs=ctx.absence_reasons||[],reasons=abs.map(x=>x.reason.replace(/^Motivo:\s*/i,'')),sleepAvg=ctx.sleep_summary?.average_hours??null,sleepTarget=ctx.sleep_summary?.target_average_hours??smartSleepTarget();const train=avg('training_pct'),food=avg('nutrition_pct'),water=avg('hydration_pct'),score=d.length?Math.round(d.reduce((a,x)=>a+(+x.score||0),0)/d.length):0,prev=ctx.previous_weekly_review,prevSleep=prev?.context?.sleep_summary?.average_hours??null,delta=prev?` Comparado ao Radar anterior: treino ${prev.training_pct}%→${train}%, alimentação ${prev.nutrition_pct}%→${food}%, hidratação ${prev.hydration_pct}%→${water}% e aderência ${prev.average_score}→${score}${prevSleep!==null&&sleepAvg!==null?`, sono ${Number(prevSleep).toFixed(1).replace('.',',')}h→${Number(sleepAvg).toFixed(1).replace('.',',')}h`:''}.`:'';return{summary:`${d.length} dia(s) concluído(s), Σ Score médio ${score}. Treino ${train}%, alimentação ${food}% e hidratação ${water}%.${sleepAvg!==null?` Sono médio ${Number(sleepAvg).toFixed(1).replace('.',',')} h para meta aproximada de ${Number(sleepTarget).toFixed(1).replace('.',',')} h.`:''}${abs.length?` Foram registradas ${abs.length} ausência(s): ${reasons.join(', ')}.`:''}${delta}`,keep:train>=80?'A consistência dos treinos e a progressão gradual.':water>=85?'A regularidade da hidratação.':'O registro fiel da rotina, inclusive nos dias imperfeitos.',increase:train<75?'A aderência ao treino ou ajustar a frequência para caber melhor na rotina.':water<80?'A constância da hidratação.':food<80?'A regularidade alimentar/proteica.':sleepAvg!==null&&sleepAvg<sleepTarget*.9?'A recuperação: sono médio abaixo da meta inteligente.':'A progressão de cargas sem sacrificar recuperação.',reduce:reasons.filter(x=>/PREGUIÇA/i.test(x)).length?'As barreiras dos dias em que a motivação caiu; vale simplificar ou redistribuir essas sessões.':sleepAvg!==null&&sleepAvg<sleepTarget*.85?'Acúmulo de fadiga e excesso de volume enquanto o sono estiver abaixo da meta.':'Mudanças bruscas; preserve recuperação e ajuste só o que os dados justificarem.',next:'Usar treino, alimentação, hidratação, passos, sono e recuperação em conjunto para ajustar a próxima programação.'}}
async function askCoachReview(mode,start,end){const ctx=reviewContext(start,end,mode);try{const {data,error}=await sb.functions.invoke('coach',{body:{message:mode==='weekly'?'Feche meu Σ Radar Semanal com uma análise completa e realista.':'Feche meu Σ Radar Mensal com tendências, evolução e próximos passos.',current_date:end,review_mode:mode,review_context:ctx,plan:{calories:S.plan.cal,protein:S.plan.prot,carbs:S.plan.carb,fat:S.plan.fat,water:S.plan.water,meals:S.plan.meals,exercises:S.plan.exercises,activities:S.plan.activities||[],exercise_library:[]},client_progress:{}}});if(error)throw error;if(data?.review)return data.review}catch(e){console.warn('Review IA indisponível; usando análise local',e)}return fallbackReview(ctx)}
function showRadarClosing(kind,stage='loading',review=null){const m=$('#radarCloseModal');m.dataset.kind=kind;$('#radarCloseEyebrow').textContent=kind==='weekly'?'Σ RADAR SEMANAL':'Σ RADAR MENSAL';$('#radarCloseTitle').textContent=stage==='loading'?'Σ Coach está lendo seus dados...':'Seu Radar está pronto.';$('#radarCloseText').textContent=stage==='loading'?'Treino, alimentação, hidratação, sono, atividades, ausências, cargas, evolução e rotina estão entrando na análise.':(review?.summary||'Análise concluída.');$('#radarCloseSteps').innerHTML=stage==='loading'?'<span>◌ Treinos e atividades</span><span>◌ Alimentação e hidratação</span><span>◌ Ausências e rotina</span><span>◌ Evolução, cargas e tendências</span>':'<span>✓ Dados consolidados</span><span>✓ Padrões identificados</span><span>✓ Insights do Σ Coach prontos</span>';$('#radarCloseAction').style.display=stage==='ready'?'block':'none';m.classList.add('open')}
function openClosedRadar(){const m=$('#radarCloseModal'),kind=m.dataset.kind;if(kind==='monthly'&&m.dataset.periodStart){S.radarMonthView=m.dataset.periodStart;renderMonthly()}m.classList.remove('open');go(kind==='weekly'?'weekly':'monthly')}
function renderWeekCloseButton(){const targets=['#weekCloseWrap','#homeWeekCloseWrap'].map(q=>$(q)).filter(Boolean);if(!targets.length)return;const r=weekRange(),today=S.currentDate||localDate(),isSunday=dayNameForDate(today)==='Domingo',done=completedWeekDays(r),closed=S.weeklyReviews.some(x=>x.week_start===r.start);let html;if(closed)html='<div class="weekCloseDone">✓ SEMANA ENCERRADA — Radar salvo no histórico.</div>';else if(!isSunday)html='<div class="weekCloseHint">O fechamento semanal será liberado no domingo.</div>';else{const missing=r.dates.filter(d=>!done.some(x=>x.log_date===d)),missingText=missing.map(formatDate).join(' • ');html=`<button class="big full ${done.length<7?'weekClosePending':''}" onclick="closeMyWeek()">ENCERRAR MINHA SEMANA</button><small>${done.length}/7 dias registrados como concluídos nesta semana.${missing.length?` Falta concluir: ${missingText}.`:''}</small>`}targets.forEach(el=>el.innerHTML=html)}
async function closeMyWeek(){const r=weekRange(),days=completedWeekDays(r),missing=r.dates.filter(d=>!days.some(x=>x.log_date===d));if(dayNameForDate(S.currentDate)!=='Domingo')return toast('O fechamento semanal é liberado no domingo.');if(missing.length)return toast('Falta concluir: '+missing.map(formatDate).join(' • '));showRadarClosing('weekly','loading');const review=await askCoachReview('weekly',r.start,r.end),avg=k=>Math.round(days.reduce((a,x)=>a+(+x[k]||0),0)/days.length);const {data,error}=await sb.from('weekly_reviews').upsert({user_id:session.user.id,week_start:r.start,average_score:avg('score'),training_pct:avg('training_pct'),nutrition_pct:avg('nutrition_pct'),hydration_pct:avg('hydration_pct'),summary:review.summary,keep_text:review.keep,increase_text:review.increase,reduce_text:review.reduce,proposed_changes:{next:review.next,context:reviewContext(r.start,r.end,'weekly')},user_approved:true},{onConflict:'user_id,week_start'}).select().single();if(error){$('#radarCloseModal').classList.remove('open');return toast(error.message)}S.weeklyReviews=[data,...S.weeklyReviews.filter(x=>x.week_start!==r.start)];renderHist();renderWeekCloseButton();showRadarClosing('weekly','ready',review)}
function previousMonthRange(){const now=new Date(),firstThis=new Date(now.getFullYear(),now.getMonth(),1),lastPrev=new Date(now.getFullYear(),now.getMonth(),0),firstPrev=new Date(lastPrev.getFullYear(),lastPrev.getMonth(),1);return{start:localDate(firstPrev),end:localDate(lastPrev)}}
async function checkAutomaticMonthlyClose(){if(!session||!S.history.length)return;const r=previousMonthRange();if(S.monthlyReviews.some(x=>x.month_start===r.start))return;const hasData=S.history.some(x=>x.log_date>=r.start&&x.log_date<=r.end&&x.status==='completed');if(!hasData)return;showRadarClosing('monthly','loading');const review=await askCoachReview('monthly',r.start,r.end),ctx=reviewContext(r.start,r.end,'monthly'),d=ctx.daily_logs.filter(x=>x.status==='completed'),avg=k=>d.length?Math.round(d.reduce((a,x)=>a+(+x[k]||0),0)/d.length):null;const body=ctx.body_logs.slice().sort((a,b)=>a.log_date.localeCompare(b.log_date)),fw=body.find(x=>x.weight_kg)?.weight_kg,lw=[...body].reverse().find(x=>x.weight_kg)?.weight_kg;const row={user_id:session.user.id,month_start:r.start,average_score:avg('score'),training_pct:avg('training_pct'),nutrition_pct:avg('nutrition_pct'),hydration_pct:avg('hydration_pct'),weight_delta_kg:fw&&lw?lw-fw:null,summary:review.summary,evolution_text:review.keep,highlight_text:review.increase,next_text:review.next||review.reduce,details:ctx};const {data,error}=await sb.from('monthly_reviews').upsert(row,{onConflict:'user_id,month_start'}).select().single();if(error){console.warn(error);$('#radarCloseModal').classList.remove('open');return}S.monthlyReviews=[data,...S.monthlyReviews.filter(x=>x.month_start!==r.start)];$('#radarCloseModal').dataset.periodStart=r.start;showRadarClosing('monthly','ready',review)}

function deltaLabel(a,b,suffix='%'){if(a===null||a===undefined||b===null||b===undefined)return'—';const d=Math.round((+b)-(+a)),arrow=d>0?'↑':d<0?'↓':'→';return`${Math.round(+a)}${suffix} → ${Math.round(+b)}${suffix} ${arrow} ${d>0?'+':''}${d}${suffix==='%'?' p.p.':''}`}
