async function saveEvolution(){
 try{
  const num=id=>{const s=String($('#'+id).value??'').trim().replace(',','.');return s===''?null:Number(s)};
  const w=num('pfWeight'),waist=num('pfWaist'),fat=num('pfFat');
  if([w,waist,fat].some(v=>v!==null&&Number.isNaN(v)))return toast('Revise os valores informados.');
  if(w===null&&waist===null&&fat===null)return toast('Informe ao menos um dado.');
  const row={user_id:session.user.id,log_date:S.currentDate||localDate()};
  if(w!==null)row.weight_kg=w;if(waist!==null)row.waist_cm=waist;if(fat!==null)row.body_fat_pct=fat;
  const {error}=await sb.from('body_logs').upsert(row,{onConflict:'user_id,log_date'});
  if(error)throw error;
  if(w!==null)await updateProfileFields({current_weight_kg:w});
  if(steps!==null)S.steps=Math.round(steps);
  ['pfWeight','pfWaist','pfFat'].forEach(id=>$('#'+id).value='');
  await loadEvolutionData();renderProfile();renderMonthly();progress();toast('Evolução registrada ✓');
 }catch(e){console.error('saveEvolution',e);toast('Não foi possível salvar a evolução: '+(e?.message||e))}
}
